import React, { useState, useRef, useEffect } from "react";
// import { DateRange } from "react-date-range";
// import { enUS } from "date-fns/locale"; // Import locale
// import "react-date-range/dist/styles.css";
// import "react-date-range/dist/theme/default.css";
import { DateRange } from "react-date-range";
import { enUS } from "date-fns/locale";
import "react-date-range/dist/styles.css";
import "react-date-range/dist/theme/default.css";
import { FaCalendarAlt } from "react-icons/fa"; // Calendar icon
import DataTable from "react-data-table-component";
import { makeApiRequest } from "../axiosService/ApiCall";
import { Spinner } from "react-bootstrap";
import Select from "react-select";
import eth from "../Assets/images/ethereum.png";
import btc from "../Assets/images/btc.png";
import sol from "../Assets/images/solana.png";
import ltc from "../Assets/images/litecoin.png";
import car from "../Assets/images/cardano.png";
import { MdRefresh } from "react-icons/md";

const cryptoData = [
  { img: eth, textOne: "ETHUSDT", textTwo: "Ethereum" },
  { img: btc, textOne: "BTCUSDT", textTwo: "Bitcoin" },
  { img: sol, textOne: "SOLUSDT", textTwo: "Solana" },
  { img: ltc, textOne: "LTCUSDT", textTwo: "Litecoin" },
  { img: car, textOne: "ADAUSDT", textTwo: "Cardano" },
];

function Tradehistory() {
  const [tradeData, setTradeData] = useState([]);
  const [pairName, setPairName] = useState("");
  const [type, setType] = useState("");
  const [status, setStatus] = useState("");
  const [fromDate, setFromDate] = useState("");
  const [toDate, setToDate] = useState("");
  const [selectedSymbol, setSelectedSymbol] = useState("");

  const [search, setSearch] = useState("");
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(0);
  const [loading, setLoading] = useState(true);
  const [limit, setLimit] = useState(10);
  const [showCalendar, setShowCalendar] = useState(false);
  const [totalItems, setTotalItems] = useState(0);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [is_Refreshing, setIs_Refreshing] = useState(false);
  const [resetPaginationToggle, setResetPaginationToggle] = useState(false);
  const [range, setRange] = useState([
    {
      startDate: new Date(),
      endDate: new Date(),
      key: "selection",
    },
  ]);
  const calendarRef = useRef(null);

  const formatWithoutRounding = (value, decimals) => {
    const factor = Math.pow(10, decimals);
    return Math.floor(value * factor) / factor;
  };

  const userpower = (x) => {
    x = x.toString();

    if (x.includes('e-')) {
      const [num, exp] = x.split('e-');
      const e = parseInt(exp);
      const digits = num.replace('.', '');
      const result = '0.' + '0'.repeat(e - 1) + digits;
      return result;
    } else if (x.includes('e+')) {
      const [num, exp] = x.split('e+');
      const e = parseInt(exp);
      const [intPart, decPart = ''] = num.split('.');
      let fullNum = intPart + decPart;
      while (fullNum.length < intPart.length + e) {
        fullNum += '0';
      }
      const decimal = fullNum.slice(0, intPart.length + e) + '.' + fullNum.slice(intPart.length + e);
      return decimal;
    }

    return x;
  }

  const handleChange = (selectedOption) => {
    handleReset()
    setPairName(selectedOption ? selectedOption.value : "");
  };

  const handleReset = async () => {
    setLimit(10);
    setCurrentPage(1);
    setResetPaginationToggle(!resetPaginationToggle);
  }

  // const cryptoOptions = cryptoData.map((data) => ({

  //   value: data.textOne,
  //   label: (
  //     <div style={{ display: "flex", alignItems: "center" }}>
  //       <img
  //         src={data.img}
  //         alt={data.textOne}
  //         style={{ width: 20, height: 20, marginRight: 10 }}
  //       />
  //       {data.textOne}
  //     </div>
  //   ),
  // }));


  const cryptoOptions = cryptoData.map((data) => {
    // Split the symbol into base and quote (e.g., SOLUSDT → SOL + USDT)
    const base = data.textOne.slice(0, -4); // e.g., SOL
    const quote = data.textOne.slice(-4);   // e.g., USDT
    const displayText = `${base}/${quote}`;

    return {
      value: data.textOne,
      label: (
        <div style={{ display: "flex", alignItems: "center" }}>
          <img
            src={data.img}
            alt={data.textOne}
            style={{ width: 20, height: 20, marginRight: 10 }}
          />
          {displayText}
        </div>
      ),
    };
  });


  // Close calendar when clicking outside
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (calendarRef.current && !calendarRef.current.contains(event.target)) {
        setShowCalendar(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const getTradehistory = async (page = 1) => {
    try {
      let queryParams = new URLSearchParams({
        pairName: pairName || "",
        type: type || "",
        search: search || "",
        status: status || "",
        fromDate: fromDate || "",
        toDate: toDate || "",
        page: page,
        limit: limit,
      }).toString();
      let params = {
        url: `user-OrderHistory?${queryParams}`,
        method: "GET",
      };
      const response = await makeApiRequest(params);
      if (response.status) {
        setTradeData(response.data);
        setLoading(false);
        setTotalPages(response.pagination.totalPages);
        setTotalItems(response.pagination.totalItems)
      } else {
        setTradeData([]);
        setLoading(false);
      }
    } catch (error) {
      console.log("error---", error);
      setLoading(false);
    }
  };

  useEffect(() => {
    getTradehistory(currentPage);
  }, [pairName, type, search, status, fromDate, toDate, currentPage, limit]);

  const handleClearFilters = async () => {
    setIsRefreshing(true); // Start spinning
    setSearch("");
    setPairName("");
    setType("");
    setStatus("");
    setFromDate("");
    setToDate("");
    setShowCalendar("")
    setCurrentPage(1);
    setLimit(10);
    setIs_Refreshing(is_Refreshing ? false : true);
    getTradehistory(1);

    const start = Date.now();

    const elapsed = Date.now() - start;
    if (elapsed < 500) {
      // ensure at least 500ms rotation
      await new Promise(resolve => setTimeout(resolve, 500 - elapsed));
    }


    setIsRefreshing(false); // Stop spinning
  };

  const dateFormat = (date) => {
    try {
      const orgDate = new Date(date).toUTCString();
      // console.log('orgDate', orgDate)
      const hours = new Date(date).getUTCHours();
      const amOrPm = hours >= 12 ? "PM" : "AM";
      const formattedDate = orgDate.split(",")[1].split("GMT")[0] + amOrPm;
      return formattedDate;
    } catch (e) {
      return "Invalid Date Format";
    }
  };
  const capitalizeWords = (str) =>
    str.replace(/\b\w/g, (char) => char.toUpperCase());

  const columnsone = [
    {
      name: "S.No",
      selector: (row, index) => (currentPage - 1) * limit + index + 1,
      sortable: true,
      width: "75px",
    },
    {
      name: "Email",
      selector: (row) => row.tradeOrderData.email || "--",
      sortable: true,
      width: "250px",
    },
    {
      name: "Type",
      selector: (row) => (
        <span className="text-capitalize">{row.type || "--"}</span>
      ),
      sortable: true,
      width: "100px",
    },
    {
      name: "Pair Name",
      selector: (row) =>
        row.pairName
          ? `${row.pairName.substring(0, 3)}/${row.pairName.substring(3, 7)}`
          : "--",
      sortable: true,
      width: "130px",
    },
    {
      name: "Order Type",
      selector: (row) => (
        <span className="text-capitalize">{row.orderType || "--"}</span>
      ),
      sortable: true,
      width: "130px",
    },
    {
      name: 'Price',
      selector: row => formatWithoutRounding(row.price, 8) || "--",
      sortable: true,
    },
    {
      name: "Amount",
      selector: (row) => userpower(formatWithoutRounding(userpower(row.amount), 8)),
      sortable: true,
      width: "110px",
    },

    {
      name: "Filled Amount",
      selector: (row) => userpower(formatWithoutRounding(userpower(row.filledAmount), 8)),
      sortable: true,
      width: "150px",
    },
    {
      name: "Total",
      selector: (row) => userpower(formatWithoutRounding(userpower(row.total), 8)) || "--",
      sortable: true,
      width: "110px",
    },
    // {
    //   name: "Fee",
    //   selector: (row) => row.fee || "--",
    //   sortable: true,
    // },
    {
      name: "Fee Status",
      selector: (row) => capitalizeWords(row.feeStatus) || "--",
      sortable: true,
      width: "110px",
    },
    {
      name: "Status",
      selector: (row) => {
        const status = row.status?.toLowerCase();
        if (status === "cancelled" || status === "partially cancelled") {
          return "Cancelled";
        }
        return capitalizeWords(status) || "--";
      },
      sortable: true,
    },
    // {
    //   name: "Status",
    //   selector: (row) => capitalizeWords(row.status) || "--",
    //   sortable: true,
    // },
    {
      name: "Date(UTC)",
      selector: (row) => dateFormat(row.dateTime) || "--",
      sortable: true,
      width: "250px",
    },
  ];

  const handleDateChange = (item) => {
    setRange([item.selection]);

    const formatDate = (date) => {
      return date.toLocaleDateString("en-CA");
    };

    setFromDate(formatDate(item.selection.startDate));
    setToDate(formatDate(item.selection.endDate));
    setCurrentPage(1);
  };
  const handleSearchChange = (e) => {
    setSearch(e.target.value);
    handleReset()
  };
  const customStyles = {
    control: (base, state) => ({
      ...base,
      borderColor: state.isFocused ? "var(--color-1)" : "var(--color-1)",
      boxShadow: state.isFocused ? "0 0 0 1px var(--color-1)" : "none",
      borderRadius: "8px",
      fontSize: "13px",
      "&:hover": {
        borderColor: "var(--color-1)",
      },
      minWidth: "140px",
    }),
    menu: (base) => ({
      ...base,
      borderRadius: "8px",
      marginTop: 4,
    }),
    singleValue: (base) => ({
      ...base,
      color: "#000",
    }),
    option: (base, state) => ({
      ...base,
      backgroundColor: state.isSelected
        ? "var(--color-1)"
        : state.isFocused
          ? "#58f9b07c"
          : "white",
      color: state.isSelected ? "var(--theme-text-1)" : "black",
      ":active": {
        backgroundColor: "var(--color-1)",
      },
      cursor: "pointer",
      fontSize: "13px",
    }),
    menuPortal: (base) => ({
      ...base,
      zIndex: 9999,
    }),
  };


  return (
    <div className="App">
      <div className="container-fluid " >
        <div className=" text-dark">
          <div className="row">
            <div className="col-lg-12">
              <div className="py-3 justify-content-center d-flex justify-content-between">
                <h3 className="component-user text-center ms-lg-0">
                  Order History
                </h3>
              </div>
              <div className="d-flex calendor-form align-items-end">
                <form className="d-flex gap-lg-2 align-items-end flex-wrap">
                  <div className="mb-3">
                    <label for="exampleInputEmail1" className="form-label">
                      Email
                    </label>
                    <input
                      type="text"
                      className="form-control search-bar"
                      id="exampleInputEmail1"
                      aria-describedby="emailHelp"
                      placeholder="Email..."
                      value={search}
                      onChange={handleSearchChange}
                      style={{ width: "220px" }}
                    />
                  </div>
                  <div className="mb-3">
                    <label for="exampleInputPassword1" className="form-label">
                      Currency
                    </label>
                    <Select
                      // styles={{ minWidth: "200px" }}
                      options={cryptoOptions}
                      value={
                        pairName
                          ? cryptoOptions.find((option) => option.value === pairName)
                          : null
                      }
                      onChange={handleChange}
                      id="border-css"
                      isClearable
                      styles={customStyles}
                      isSearchable={false}
                      components={{
                        IndicatorSeparator: () => null,
                      }}
                    />
                  </div>
                  <div className="mb-3">
                    <label for="exampleInputPassword1" className="form-label">
                      Transaction Status
                    </label>
                    <select
                      className="form-select search-bar"
                      aria-label="Default select example"
                      value={status}
                      onChange={(e) => { setStatus(e.target.value); handleReset() }}
                    >
                      <option value="">All Status</option>
                      <option value="filled">Filled</option>
                      {/* <option value="pending">Pending</option> */}
                      <option value="cancelled">Cancelled</option>
                      <option value="active">Active</option>
                      <option value="partially">Partially</option>
                      {/* <option value="notMatch">Not Match</option> */}
                    </select>
                  </div>
                  <div className="mb-3">
                    <label for="exampleInputPassword1" className="form-label">
                      Type
                    </label>
                    <select
                      className="form-select search-bar"
                      aria-label="Default select example"
                      value={type}
                      onChange={(e) => { setType(e.target.value); handleReset() }}
                    >
                      <option value="">All Types</option>
                      <option value="limit">Limit</option>
                      <option value="market">Market</option>
                    </select>
                  </div>
                  {/* <div class="mb-3">
                                        <label for="exampleInputPassword1" class="form-label">Currency</label>
                                        <select class="form-select" aria-label="Default select example">
                                            <option selected>Open this select menu</option>
                                            <option value="1">One</option>
                                            <option value="2">Two</option>
                                            <option value="3">Three</option>
                                        </select>
                                    </div> */}
                  <div className="mb-3">
                    <label for="exampleInputPassword1" className="form-label">
                      Date
                    </label>

                    <div
                      ref={calendarRef}
                      style={{ position: "relative", width: "250px" }}
                    >
                      <div
                        onClick={() => { setShowCalendar(!showCalendar); handleReset() }}
                        style={{
                          display: "flex",
                          alignItems: "center",
                          justifyContent: "space-between",
                          padding: "6px",
                          border: "1px solid var(--color-1)",
                          borderRadius: "5px",
                          cursor: "pointer",
                          backgroundColor: "#fff",
                          fontSize: "14px",
                        }}
                      >
                        <span>
                          {fromDate && toDate
                            ? `${fromDate} - ${toDate}`
                            : "Select Date Range"}
                          {/* {range[0].startDate.toLocaleDateString()} - {range[0].endDate.toLocaleDateString()} */}
                        </span>
                        <FaCalendarAlt style={{ color: "#555" }} />
                      </div>

                      {/* Date range picker (shows when input is clicked) */}
                      {showCalendar && (
                        <div
                          style={{
                            position: "absolute",
                            top: "100%",
                            left: -80,
                            zIndex: 1000,
                            background: "#fff",
                            boxShadow: "0px 4px 6px rgba(0,0,0,0.1)",
                            borderRadius: "5px",
                          }}
                        >
                          <DateRange
                            editableDateInputs={true}
                            onChange={handleDateChange}
                            moveRangeOnFirstSelection={false}
                            ranges={range}
                            locale={enUS}
                            rangeColors={["#58f9b0"]}
                          />
                        </div>
                      )}
                    </div>
                  </div>
                  <div className="mb-2">
                    <button
                      type="button"
                      className="form-label custom-nav-button-1 active cursor-pointer"
                      onClick={handleClearFilters}
                      disabled={isRefreshing}
                    >
                      <MdRefresh
                        style={{ fontSize: "24px" }}
                        className={isRefreshing ? "rotate-icon" : ""}
                      />
                    </button>
                  </div>
                </form>
              </div>

              <div className="liquidity-table-1">
                {/* {loading ? (
                  <div className="text-center">
                    <Spinner animation="border" />
                  </div>
                ) : ( */}
                <DataTable
                  key={is_Refreshing}
                  columns={columnsone}
                  data={tradeData}
                  theme="solarized"
                  defaultSortAsc={true}
                  pagination
                  paginationServer
                  persistTableHead
                  paginationPerPage={limit}
                  paginationTotalRows={totalItems}
                  paginationRowsPerPageOptions={[5, 10, 15]}
                  paginationResetDefaultPage={resetPaginationToggle}
                  onChangeRowsPerPage={(newRowsPerPage) => {
                    setLimit(newRowsPerPage);
                    setCurrentPage(1);
                  }}
                  onChangePage={(page) => setCurrentPage(page)}
                  progressPending={loading}
                  progressComponent={
                    <div className="py-4 w-100" style={{ marginLeft: "45vw" }}>
                      <Spinner animation="border" />
                    </div>
                  }
                />
                {/* )} */}
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default Tradehistory;
